const { useRef, useState } = React;

const IMAGE = "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/download%20(1)_2e3ab49f-a572-4d6a-98bb-9f1a080eed38.png";
const NATURAL = 36;
const MODES = [
  { value: "auto", note: "浏览器决定，通常平滑" },
  { value: "smooth", note: "仅 Firefox 支持" },
  { value: "pixelated", note: "保留像素方块" },
  { value: "crisp-edges", note: "保持边缘锐利" },
];

const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

// 浮在舞台角上的标签：说明这一半用的是哪种算法
const Badge = ({ children, className }) => (
  <span className={`pointer-events-none absolute top-2 rounded-full bg-surface/90 px-2 py-0.5 font-tau-mono text-tau-tiny text-ink-2 shadow-card ${className}`}>
    {children}
  </span>
);

const Component = () => {
  const stageRef = useRef(null);
  const [mode, setMode] = useState("pixelated");
  const [zoom, setZoom] = useState(8);
  const [split, setSplit] = useState(50);
  const size = NATURAL * zoom;

  // 拖动分割线：左半边固定 auto，右半边是当前选中的算法
  const moveSplit = event => {
    const rect = stageRef.current.getBoundingClientRect();
    if (!rect.width) return;
    setSplit(Math.min(100, Math.max(0, ((event.clientX - rect.left) / rect.width) * 100)));
  };
  const startDrag = event => {
    event.currentTarget.setPointerCapture?.(event.pointerId);
    moveSplit(event);
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(200px,32%)]">
        <div className="flex min-w-0 items-center justify-center rounded-tau-md border border-line-1 p-4">
          <div
            ref={stageRef}
            onPointerDown={startDrag}
            onPointerMove={event => event.buttons && moveSplit(event)}
            className="relative aspect-square max-w-full cursor-ew-resize touch-none select-none overflow-hidden rounded-tau-sm border border-line-1"
            style={{ width: size }}
          >
            <img src={IMAGE} alt="" draggable={false} className="absolute inset-0 size-full" style={{ imageRendering: "auto" }} />
            <img
              src={IMAGE}
              alt=""
              draggable={false}
              className="absolute inset-0 size-full"
              style={{ imageRendering: mode, clipPath: `inset(0 0 0 ${split}%)` }}
            />
            <div className="pointer-events-none absolute inset-y-0 w-0.5 -translate-x-1/2 bg-accent" style={{ left: `${split}%` }}>
              <span className="absolute left-1/2 top-1/2 grid size-6 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-accent text-ink-inverse shadow-card">
                <icons.ChevronsLeftRight className="size-3.5" />
              </span>
            </div>
            <Badge className="left-2">auto</Badge>
            <Badge className="right-2">{mode}</Badge>
          </div>
        </div>
        <div className="flex flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">原图</span>
          <div className="flex items-center gap-3">
            <img src={IMAGE} alt="" className="shrink-0 rounded-tau-sm border border-line-1" style={{ width: NATURAL, height: NATURAL }} />
            <span className="font-tau-mono text-tau-sm text-ink-2">{NATURAL}×{NATURAL}</span>
          </div>
          <div className="flex flex-col gap-1.5">
            {MODES.map(item => (
              <button
                key={item.value}
                type="button"
                aria-pressed={mode === item.value}
                onClick={() => setMode(item.value)}
                className={`flex cursor-pointer items-center gap-2 rounded-tau-sm border px-2.5 py-1.5 text-left transition-colors ${
                  mode === item.value ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
                }`}
              >
                <span className="font-tau-mono text-tau-sm">{item.value}</span>
                <span className="ml-auto text-tau-tiny text-ink-3">{item.note}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <label className="flex min-w-[220px] flex-1 items-center gap-3">
          <span className="shrink-0 text-tau-sm text-ink-2">放大倍数</span>
          <input
            type="range"
            min={2}
            max={10}
            value={zoom}
            onChange={event => setZoom(Number(event.target.value))}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
          />
          <span className="w-10 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{zoom}×</span>
        </label>
        <span className="font-tau-mono text-tau-sm text-ink-3">
          {NATURAL}×{NATURAL} → {size}×{size}
        </span>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <Chip>image-rendering: {mode}</Chip>
        <span className="text-tau-meta text-ink-3">拖动分割线对照左侧的 auto</span>
      </div>
    </div>
  );
};
